makePalette();
const random=()=>Math.random();
function put(x,y,name){if(!inside(x,y))return;const p=idx(x,y),id=idOf[name];if(!id)return;grid[p]=id;life[p]=name==='fire'?18+random()*30:name==='spark'?7:name==='plant'?60:name==='seed'?0:0}
function swap(a,b){const t=grid[a];grid[a]=grid[b];grid[b]=t;const l=life[a];life[a]=life[b];life[b]=l;updated[a]=updated[b]=1}
function clear(){grid.fill(0);life.fill(0);document.querySelector('#hint').style.opacity=1;setTimeout(()=>document.querySelector('#hint').style.opacity=0,3500)}
function tick(){updated.fill(0);const dir=random()<.5?1:-1;for(let y=H-1;y>=0;y--){const start=dir===1?0:W-1,end=dir===1?W:-1;for(let x=start;x!==end;x+=dir){const p=idx(x,y),id=grid[p];if(!id||updated[p])continue;const name=ids[id],type=mats[name].type;let moved=false;
if(type==='powder'||type==='seed'||type==='liquid'||type==='acid'||type==='lava'||type==='gas'||type==='fire'||type==='spark'){
 let dy=(type==='gas'||type==='fire'||type==='spark')?-1:1,fall=inside(x,y+dy)?idx(x,y+dy):-1;
 if(type==='fire'||type==='spark'||type==='gas'){
   if(type==='fire'&&life[p]--<=0){grid[p]=name==='fire'&&random()<.16?idOf.smoke:0;life[p]=0;continue}if(type==='spark'&&life[p]--<=0){grid[p]=0;continue}if(type==='gas'&&random()<.012){grid[p]=0;continue}
   if(type==='fire'&&inside(x,y-1)&&random()<.075){const q=idx(x,y-1);if(grid[q]===idOf.smoke)swap(p,q)}
   if(type==='fire'){for(const [nx,ny] of [[x+1,y],[x-1,y],[x,y+1],[x,y-1]])if(inside(nx,ny)){const q=idx(nx,ny),n=ids[grid[q]];if((n==='wood'||n==='oil'||n==='gunpowder'||n==='plant'||n==='seed')&&random()<.095){grid[q]=idOf.fire;life[q]=18+random()*22}else if(n==='water'&&random()<.12){grid[p]=idOf.steam;life[p]=0}}}
   if(fall>=0&&grid[fall]===0&&random()<.7){swap(p,fall);moved=true}else{const nx=x+(random()<.5?-1:1);if(inside(nx,y+dy)&&grid[idx(nx,y+dy)]===0&&random()<.55){swap(p,idx(nx,y+dy));moved=true}else if(inside(x+(random()<.5?-1:1),y)&&grid[idx(x+(random()<.5?-1:1),y)]===0&&random()<.4){const q=idx(x+(random()<.5?-1:1),y);swap(p,q);moved=true}}
 }else{
   if((type==='acid'||type==='lava')&&random()<.22){for(const [nx,ny] of [[x+1,y],[x-1,y],[x,y+1],[x,y-1]])if(inside(nx,ny)){const q=idx(nx,ny),victim=ids[grid[q]];if(grid[q]&&victim!=='wall'&&victim!=='metal'&&victim!=='lava'&&victim!=='acid'&&random()<.24){grid[q]=type==='lava'&&random()<.3?idOf.stone:0;if(type==='acid')life[p]=Math.min(255,life[p]+1)}}}
   if(name==='water'){for(const [nx,ny] of [[x+1,y],[x-1,y],[x,y-1]])if(inside(nx,ny)&&grid[idx(nx,ny)]===idOf.fire&&random()<.5){grid[idx(nx,ny)]=idOf.steam;life[idx(nx,ny)]=0}}
   if(name==='ice'&&random()<.002){grid[p]=idOf.water}
   if(fall>=0){const target=grid[fall],targetType=target?mats[ids[target]].type:'empty';if(!target||((type==='liquid'||type==='acid'||type==='lava')&&(targetType==='powder'||targetType==='seed'))){swap(p,fall);moved=true}}
   if(!moved){const side=random()<.5?-1:1;for(const dx of [side,-side]){const nx=x+dx,ny=y+dy;if(inside(nx,ny)){const q=idx(nx,ny),target=grid[q],tt=target?mats[ids[target]].type:'empty';if(!target||((type==='liquid'||type==='acid'||type==='lava')&&(tt==='powder'||tt==='seed'))){swap(p,q);moved=true;break}}}}
 }
}
if(!moved&&name==='seed'&&y>1&&random()<.025){const below=grid[idx(x,y+1)];if(below===idOf.soil||below===idOf.sand){grid[p]=idOf.plant;life[p]=70}}
if(!moved&&(name==='plant'||name==='moss')&&random()<.018){const nx=x+(random()<.5?-1:1),ny=y-1;if(inside(nx,ny)){const q=idx(nx,ny);if(!grid[q]&&(grid[idx(x,y+1)]===idOf.soil||grid[idx(x,y+1)]===idOf.wood||grid[idx(x,y+1)]===idOf.plant)){grid[q]=idOf.plant;life[q]=60}}}
if(!moved&&(name==='fish'||name==='mouse')){const water=name==='fish';if(random()<.18){const dx=random()<.5?-1:1,dy=water?(random()<.3?-1:1):(random()<.25?-1:1),nx=x+dx,ny=y+dy;if(inside(nx,ny)){const q=idx(nx,ny),can=water?(grid[q]===0||grid[q]===idOf.water):(grid[q]===0||grid[q]===idOf.soil);if(can){if(water&&grid[q]===idOf.water)grid[q]=0;swap(p,q);moved=true}}}}
if(!moved&&name==='bacteria'&&random()<.012){const nx=x+(random()<.5?-1:1),ny=y+(random()<.5?-1:1);if(inside(nx,ny)){const q=idx(nx,ny);if(grid[q]===idOf.water||grid[q]===idOf.soil){grid[q]=idOf.bacteria;life[q]=0}}}
if(!moved&&name==='fire'&&random()<.045){const nx=x+(random()<.5?-1:1),ny=y-1;if(inside(nx,ny)&&grid[idx(nx,ny)]===0){const q=idx(nx,ny);grid[q]=idOf.fire;life[q]=12+random()*20}}
}}
}
function render(){for(let p=0;p<grid.length;p++){const id=grid[p],c=colors[id],o=p*4;if(!id){pix[o]=17;pix[o+1]=25;pix[o+2]=19;pix[o+3]=255;continue}let hex=c.slice(1),r=parseInt(hex.slice(0,2),16),g=parseInt(hex.slice(2,4),16),b=parseInt(hex.slice(4,6),16);const variation=((p*17+frame*11)%9)-4;if(ids[id]==='fire'){r=Math.min(255,r+((life[p]%5)*4));g=Math.min(255,g+((life[p]%7)*2))}else if(ids[id]==='water'||ids[id]==='mercury')b=Math.min(255,b+variation);else{r=Math.max(0,Math.min(255,r+variation));g=Math.max(0,Math.min(255,g+variation));b=Math.max(0,Math.min(255,b+variation))}pix[o]=r;pix[o+1]=g;pix[o+2]=b;pix[o+3]=255}ctx.putImageData(img,0,0);let n=0;for(let p=0;p<grid.length;p++)if(grid[p])n++;document.querySelector('#count').textContent=n.toLocaleString();frame++}

