function render(){for(let p=0;p<grid.length;p++){const id=grid[p],c=colors[id],o=p*4;if(!id){pix[o]=17;pix[o+1]=25;pix[o+2]=19;pix[o+3]=255;continue}let hex=c.slice(1),r=parseInt(hex.slice(0,2),16),g=parseInt(hex.slice(2,4),16),b=parseInt(hex.slice(4,6),16);const variation=((p*17+frame*11)%9)-4;if(ids[id]==='fire'){r=Math.min(255,r+((life[p]%5)*4));g=Math.min(255,g+((life[p]%7)*2))}else if(ids[id]==='water'||ids[id]==='mercury')b=Math.min(255,b+variation);else{r=Math.max(0,Math.min(255,r+variation));g=Math.max(0,Math.min(255,g+variation));b=Math.max(0,Math.min(255,b+variation))}pix[o]=r;pix[o+1]=g;pix[o+2]=b;pix[o+3]=255}ctx.putImageData(img,0,0);let n=0;for(let p=0;p<grid.length;p++)if(grid[p])n++;document.querySelector('#count').textContent=n.toLocaleString();frame++}
canvas.width=W;canvas.height=H;
function position(e){const r=canvas.getBoundingClientRect();return{x:Math.floor((e.clientX-r.left)/r.width*W),y:Math.floor((e.clientY-r.top)/r.height*H)}}
function stamp(x,y,material=selected){const rad=tool==='erase'?brush:brush;for(let dy=-rad;dy<=rad;dy++)for(let dx=-rad;dx<=rad;dx++){if(dx*dx+dy*dy>rad*rad)continue;const nx=x+dx,ny=y+dy;if(!inside(nx,ny))continue;if(tool==='erase'){grid[idx(nx,ny)]=0;life[idx(nx,ny)]=0}else if(grid[idx(nx,ny)]===0||mats[material].type==='wall'){put(nx,ny,material)}}}
function stroke(a,b,material=selected){const d=Math.max(Math.abs(b.x-a.x),Math.abs(b.y-a.y)),steps=Math.max(1,d);for(let i=0;i<=steps;i++){const t=i/steps;stamp(Math.round(a.x+(b.x-a.x)*t),Math.round(a.y+(b.y-a.y)*t),material)}}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();mouseDown=true;last=position(e);canvas.setPointerCapture(e.pointerId);if(tool!=='line')stamp(last.x,last.y)});
canvas.addEventListener('pointermove',e=>{if(!mouseDown)return;const p=position(e);if(tool==='draw'||tool==='erase')stroke(last,p);last=p});
function endStroke(e){if(!mouseDown)return;mouseDown=false;const p=position(e);if(tool==='line'&&last)stroke(last,p);last=null}
canvas.addEventListener('pointerup',endStroke);canvas.addEventListener('pointercancel',endStroke);
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=b.dataset.tool;document.querySelectorAll('[data-tool]').forEach(x=>x.classList.toggle('active',x===b));canvas.style.cursor=tool==='erase'?'cell':'crosshair'});
document.querySelector('#brush').oninput=e=>{brush=+e.target.value;document.querySelector('#brushVal').textContent=brush};
function pause(){running=!running;document.querySelector('#pauseBtn').textContent=running?'Ⅱ Pause':'▶ Resume';document.querySelector('#stateLabel').textContent=running?'SIMULATION LIVE':'SIMULATION PAUSED';document.querySelector('.dot').style.background=running?'#a6e864':'#e3b45e'}
document.querySelector('#pauseBtn').onclick=pause;
function starter(){clear();for(let x=0;x<W;x++){let ground=84+Math.round(Math.sin(x*.075)*4+Math.sin(x*.19)*2);for(let y=ground;y<H;y++)put(x,y,y>ground+8?'soil':'sand')}for(let x=79;x<122;x++){let surface=93+Math.floor(Math.sin((x-79)/43*Math.PI)*9);for(let y=surface;y<112;y++)if(inside(x,y))put(x,y,'water')}for(let x=0;x<W;x++)for(let y=116;y<H;y++)put(x,y,'stone');for(const x of [25,31,151,157,166]){const base=83+Math.round(Math.sin(x*.075)*4);for(let y=base-8;y<base;y++)if(y>5)put(x,y,'wood');for(let dx=-4;dx<=4;dx++)for(let dy=-5;dy<=3;dy++)if(dx*dx/17+dy*dy/19<1&&random()<.86)put(x+dx,base-8+dy,'plant')}for(let i=0;i<80;i++){const x=85+Math.floor(random()*30),y=98+Math.floor(random()*10);if(grid[idx(x,y)]===idOf.water)put(x,y,'fish')}for(let i=0;i<18;i++)put(5+Math.floor(random()*190),8+Math.floor(random()*35),'spark');toast('A tiny world is ready to explore')}
document.querySelector('#clearBtn').onclick=starter;
document.querySelector('#search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.mat').forEach(b=>b.style.display=b.dataset.name.includes(q)?'flex':'none');document.querySelectorAll('.group-wrap').forEach(g=>g.style.display=[...g.querySelectorAll('.mat')].some(b=>b.style.display!=='none')?'':'none')});
let toastTimer;function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1800)}
document.querySelector('#helpBtn').onclick=()=>toast('Drag to pour · choose any element · SPACE pauses · R resets');document.querySelector('#soundBtn').onclick=()=>toast('A quiet place to experiment');
window.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();pause()}if(e.key.toLowerCase()==='r')starter();if(e.key.toLowerCase()==='c'){clear();toast('Canvas cleared')}});
function loop(now){if(now-lastTime>=500){fps=Math.round(1000/(now-lastTime)*2);document.querySelector('#fps').textContent=fps;lastTime=now}if(running)tick();render();requestAnimationFrame(loop)}
starter();requestAnimationFrame(loop);
})();
</script></body></html>

